const data = $('Validate Follow-up Response').first().json;

return [{
  json: {
    followup_id: data.followup_id,
    application_id: data.application_id,
    user_id: data.user_id,
    response_status: data.response_status,
    is_replied: data.response_status === 'replied'
  }
}];

const db = $input.first().json;
const input = $('Validate Prep Request').first().json;

if (!db || !db.job_title) {
  throw new Error('Application not found. Check application_id and user_id.');
}

function safeJSONParse(field) {
  if (!field) return [];
  if (Array.isArray(field)) return field;
  try { return JSON.parse(field); }
  catch(e) { return field.split(',').map(i => i.trim()).filter(Boolean); }
}

const skills = safeJSONParse(db.skills);
const jobTitles = safeJSONParse(db.job_titles);
const industries = safeJSONParse(db.industries);

// Merge interviewer info: prefer webhook input over DB record
const interviewer_name = input.interviewer_name || db.interviewer_name || null;
const interviewer_role = input.interviewer_role || db.interviewer_role || null;
const interviewer_linkedin_url = input.interviewer_linkedin_url || null;

return [{
  json: {
    application_id: db.application_id,
    job_id: db.job_id,
    user_id: db.user_id,
    email: db.email,
    full_name: db.full_name,
    job_title: db.job_title,
    company_name: db.company_name,
    company_url: db.company_url || '',
    job_location: db.job_location || 'Remote',
    job_description: (db.job_description || '').substring(0, 3000),
    job_requirements: (db.job_requirements || '').substring(0, 2000),
    interview_date: db.interview_date || null,
    interview_type: db.interview_type || 'video',
    interview_location: db.interview_location || null,
    interviewer_name,
    interviewer_role,
    interviewer_linkedin_url,
    skills,
    job_titles: jobTitles,
    industries,
    experience_years: db.experience_years || 0,
    company_overview: db.company_overview || null,
    mission_and_values: db.mission_and_values || null,
    company_talking_points: db.company_talking_points || null,
    has_company_research: !!db.company_overview,
    has_interviewer: !!interviewer_name,
    has_linkedin: !!interviewer_linkedin_url
  }
}];

const prepData = $('Prepare Prep Data').first().json;
const html = $input.first().json?.body || $input.first().json?.data || '';

const stripHtml = (str) => {
  if (typeof str !== 'string') return '';
  return str
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim()
    .substring(0, 2000);
};

const bio = stripHtml(html);

return [{
  json: {
    ...prepData,
    interviewer_bio: bio.length > 100 ? bio : null,
    linkedin_scraped: bio.length > 100
  }
}];

const d = $input.first().json;
const e = (str) => (str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const today = new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' });

const questions = d.questions || {};

const renderQuestions = (list, color) => {
  if (!Array.isArray(list) || list.length === 0) return '<p style="color:#6b7280;font-style:italic">None generated.</p>';
  return list.map(q => '<div style="margin-bottom:14px;padding:12px 14px;background:#f8fafc;border-left:3px solid ' + color + ';border-radius:0 6px 6px 0">' +
    '<p style="margin:0 0 4px;font-weight:600;color:#1e3a5f;font-size:10pt">' + e(q.question) + '</p>' +
    '<p style="margin:0 0 2px;font-size:8.5pt;color:#64748b"><em>Why asked:</em> ' + e(q.why_asked) + '</p>' +
    '<p style="margin:0;font-size:8.5pt;color:#0f6e56"><em>Tip:</em> ' + e(q.tip) + '</p>' +
    '</div>'
  ).join('');
};

const renderStar = (list) => {
  if (!Array.isArray(list) || list.length === 0) return '<p style="color:#6b7280;font-style:italic">No STAR answers generated.</p>';
  return list.map((s, i) => '<div style="margin-bottom:18px;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden">' +
    '<div style="background:#1e3a5f;padding:8px 14px"><p style="margin:0;color:#fff;font-weight:600;font-size:9.5pt">' + e(s.question) + '</p></div>' +
    '<div style="padding:12px 14px">' +
    '<table style="width:100%;border-collapse:collapse;font-size:9pt">' +
    '<tr><td style="width:90px;color:#64748b;vertical-align:top;padding:4px 8px 4px 0;font-weight:600">Situation</td><td style="color:#374151;padding:4px 0">' + e(s.situation) + '</td></tr>' +
    '<tr><td style="color:#64748b;vertical-align:top;padding:4px 8px 4px 0;font-weight:600">Task</td><td style="color:#374151;padding:4px 0">' + e(s.task) + '</td></tr>' +
    '<tr><td style="color:#64748b;vertical-align:top;padding:4px 8px 4px 0;font-weight:600">Action</td><td style="color:#374151;padding:4px 0">' + e(s.action) + '</td></tr>' +
    '<tr><td style="color:#64748b;vertical-align:top;padding:4px 8px 4px 0;font-weight:600">Result</td><td style="color:#374151;padding:4px 0;font-weight:600;color:#0f6e56">' + e(s.result) + '</td></tr>' +
    '</table></div></div>'
  ).join('');
};

const questionsToAsk = Array.isArray(d.questions_to_ask) ? d.questions_to_ask.map(q => '<li style="margin-bottom:5px">' + e(q) + '</li>').join('') : '';
const dos = d.dos_and_donts?.dos || [];
const donts = d.dos_and_donts?.donts || [];
const dosHtml = dos.map(x => '<li style="margin-bottom:4px;color:#166534">' + e(x) + '</li>').join('');
const dontsHtml = donts.map(x => '<li style="margin-bottom:4px;color:#991b1b">' + e(x) + '</li>').join('');

const interviewDate = d.interview_date ? new Date(d.interview_date).toLocaleString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric', hour:'2-digit', minute:'2-digit' }) : 'Not scheduled';

const html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Interview Prep - ' + e(d.company_name) + '</title>' +
'<style>* { margin:0; padding:0; box-sizing:border-box; } body { font-family:Arial,sans-serif; font-size:10pt; color:#1a1a1a; padding:32px 40px; max-width:820px; margin:0 auto; } .header { border-bottom:3px solid #1e3a5f; padding-bottom:14px; margin-bottom:22px; } h1 { font-size:20pt; font-weight:700; color:#1e3a5f; } .sub { color:#4b5563; font-size:9.5pt; margin-top:4px; } .meta-bar { display:flex; gap:20px; flex-wrap:wrap; background:#eff6ff; padding:10px 16px; border-radius:6px; margin-bottom:22px; font-size:9pt; color:#1e40af; } .stitle { font-size:9pt; font-weight:700; color:#1e3a5f; text-transform:uppercase; letter-spacing:1px; border-bottom:2px solid #dbeafe; padding-bottom:4px; margin-bottom:12px; margin-top:22px; } .card { background:#f8fafc; border:1px solid #e2e8f0; border-radius:6px; padding:12px 16px; line-height:1.65; color:#374151; margin-bottom:14px; } .dos-donts { display:grid; grid-template-columns:1fr 1fr; gap:16px; } .dos { background:#f0fdf4; border:1px solid #bbf7d0; border-radius:6px; padding:12px 16px; } .donts { background:#fef2f2; border:1px solid #fecaca; border-radius:6px; padding:12px 16px; } ul.items { padding-left:18px; } ul.items li { line-height:1.55; } .interviewer-box { background:#fef9c3; border-left:4px solid #ca8a04; padding:12px 16px; border-radius:0 6px 6px 0; margin-bottom:14px; } .footer-note { margin-top:28px; border-top:1px solid #e5e7eb; padding-top:10px; font-size:8pt; color:#9ca3af; text-align:center; }</style></head><body>' +
'<div class="header"><h1>&#127358; Interview Prep Document</h1><div class="sub">Prepared for: <strong>' + e(d.full_name) + '</strong> &nbsp;&bull;&nbsp; Role: <strong>' + e(d.job_title) + '</strong> at <strong>' + e(d.company_name) + '</strong></div></div>' +
'<div class="meta-bar"><span><strong>Interview:</strong> ' + e(interviewDate) + '</span><span><strong>Format:</strong> ' + e(d.interview_type || 'Video') + '</span>' + (d.interview_location ? '<span><strong>Link/Location:</strong> ' + e(d.interview_location) + '</span>' : '') + '<span><strong>Generated:</strong> ' + today + '</span></div>' +
(d.interviewer_name ? '<div class="interviewer-box"><strong>&#128100; Interviewer:</strong> ' + e(d.interviewer_name) + (d.interviewer_role ? ' &mdash; ' + e(d.interviewer_role) : '') + (d.interviewer_bio ? '<br><span style="font-size:8.5pt;color:#713f12">LinkedIn: ' + e(d.interviewer_bio.substring(0,300)) + '...</span>' : '') + '</div>' : '') +
'<div class="stitle">Role Analysis</div><div class="card">' + e(d.role_analysis || '') + '</div>' +
'<div class="stitle">Behavioural Questions (5)</div>' + renderQuestions(questions.behavioural, '#2563eb') +
'<div class="stitle">Technical Questions (3)</div>' + renderQuestions(questions.technical, '#7c3aed') +
'<div class="stitle">Culture Fit Questions (3)</div>' + renderQuestions(questions.culture_fit, '#0f6e56') +
'<div class="stitle">Situational Questions (2)</div>' + renderQuestions(questions.situational, '#ca8a04') +
'<div class="stitle">STAR Answer Frameworks (3)</div>' + renderStar(d.star_answers) +
'<div class="stitle">Smart Questions to Ask</div><ul class="items" style="padding-left:18px">' + questionsToAsk + '</ul>' +
'<div class="stitle">Do\'s &amp; Don\'ts</div><div class="dos-donts"><div class="dos"><p style="font-weight:600;color:#166534;margin-bottom:8px">&#9989; Do</p><ul class="items">' + dosHtml + '</ul></div><div class="donts"><p style="font-weight:600;color:#991b1b;margin-bottom:8px">&#10060; Don\'t</p><ul class="items">' + dontsHtml + '</ul></div></div>' +
'<div class="stitle">Salary Guidance</div><div class="card">' + e(d.salary_guidance || '') + '</div>' +
(d.interviewer_insights && d.interviewer_name ? '<div class="stitle">Interviewer Insights</div><div class="card" style="background:#fef9c3;border-color:#fde68a">' + e(d.interviewer_insights) + '</div>' : '') +
'<div class="stitle">Coach\'s Notes</div><div class="card" style="font-style:italic;color:#374151">' + e(d.prep_notes || '') + '</div>' +
'<div class="footer-note">Generated by Match AI &bull; ' + today + ' &bull; Review and personalise before your interview.</div>' +
'</body></html>';

return [{ json: { ...d, prep_html: html } }];

const user = $input.first().json;
if (!user || !user.user_id) throw new Error('No active profile found.');
function safeJSONParse(field) {
  if (!field) return [];
  if (Array.isArray(field)) return field;
  if (typeof field === 'string') { try { return JSON.parse(field); } catch (e) { return field.split(',').map(i => i.trim()).filter(Boolean); } }
  return [];
}
return [{ json: { user_id: user.user_id, profile_id: user.profile_id, email: user.email, full_name: user.full_name || 'User', skills: safeJSONParse(user.skills), experience_years: user.experience_years || 0, job_titles: safeJSONParse(user.job_titles), industries: safeJSONParse(user.industries), min_salary: user.min_salary || 0, max_salary: user.max_salary || 0, preferred_locations: safeJSONParse(user.preferred_locations), work_type: user.work_type || 'any' } }];

const fetched = $input.first().json || {};
const validated = $('Validate Tailor Request').first().json;

const base64 = fetched.data_base64 || '';
const contentType = fetched.content_type || '';
const fileName = fetched.file_name || 'resume';

let quickText = '';
if (base64 && contentType.startsWith('text/')) {
  quickText = Buffer.from(base64, 'base64').toString('utf-8');
}

return [{
  json: {
    ...validated,
    original_file_name: fileName,
    original_content_type: contentType,
    original_size: fetched.size || 0,
    original_text: quickText,
    has_original_bytes: !!base64,
  },
  binary: base64 ? {
    data: {
      data: base64,
      mimeType: contentType || 'application/octet-stream',
      fileName,
    }
  } : undefined,
}];

const items = $input.all();
const merged = items[0]?.json;
const resumeCtx = $('Attach Extracted Resume Text').first()?.json || $('No Resume URL — Skip Fetch').first()?.json || {};

if (!merged || !merged.user_id) {
  throw new Error('No active profile found for user_id');
}
if (!merged.id) {
  throw new Error('No job found for job_id');
}

function safeJSONParse(field) {
  if (!field) return [];
  if (Array.isArray(field)) return field;
  if (typeof field === 'string') {
    try { return JSON.parse(field); }
    catch (e) { return field.split(',').map(i => i.trim()).filter(Boolean); }
  }
  return [];
}

return [{
  json: {
    user_id: merged.user_id,
    job_id: merged.id,
    profile_id: merged.profile_id,
    email: merged.email,
    full_name: merged.full_name || 'Candidate',
    user_location: merged.user_location || '',
    phone: merged.phone || '',
    base_resume_url: merged.base_resume_url || null,
    skills: safeJSONParse(merged.skills),
    experience_years: merged.experience_years || 0,
    job_titles: safeJSONParse(merged.job_titles),
    industries: safeJSONParse(merged.industries),
    min_salary: merged.min_salary || 0,
    max_salary: merged.max_salary || 0,
    preferred_locations: safeJSONParse(merged.preferred_locations),
    work_type: merged.work_type || 'any',
    job_title: merged.title,
    company_name: merged.company_name,
    company_url: merged.company_url || '',
    job_location: merged.location || 'Remote',
    job_work_type: merged.work_type || 'remote',
    employment_type: merged.employment_type || 'full-time',
    salary_min: merged.salary_min || null,
    salary_max: merged.salary_max || null,
    job_description: (merged.description || '').substring(0, 4000),
    job_requirements: (merged.requirements || '').substring(0, 2000),
    source_url: merged.source_url || '',
    preserve_format: resumeCtx.preserve_format === true,
    original_text: resumeCtx.original_text || '',
    original_content_type: resumeCtx.original_content_type || null,
    original_file_name: resumeCtx.original_file_name || null,
  }
}];

const data = $input.first().json;
const skills = Array.isArray(data.skills) ? data.skills : [];
const jobTitles = Array.isArray(data.job_titles) ? data.job_titles : [];
const industries = Array.isArray(data.industries) ? data.industries : [];

// Groq's llama-3.1-8b-instant caps at 6000 tokens/minute (TPM) on this org's
// on-demand tier, input + max_tokens combined. Structured JSON (no HTML
// markup to write) is much smaller than the old ask-the-model-to-write-HTML
// approach, so this budget has real headroom.
const originalResume = (data.original_text || '').slice(0, 6000);
const hasOriginal = originalResume.length > 200;

const schema = '{\n' +
  '  "professional_summary": "3-4 sentence summary tailored to the target job",\n' +
  '  "portfolio_url": "URL or null",\n' +
  '  "github_url": "URL or null",\n' +
  '  "linkedin_url": "URL or null",\n' +
  '  "skill_groups": [ { "category": "short category name", "items": ["skill1", "skill2"] } ],\n' +
  '  "projects": [ { "name": "project name", "subtitle": "one line description", "url": "URL or null", "bullets": ["achievement 1", "achievement 2"] } ],\n' +
  '  "experience": [ { "company": "COMPANY NAME", "role": "Job Title", "dates": "Month Year - Month Year", "bullets": ["achievement 1", "achievement 2"] } ],\n' +
  '  "education": [ { "institution": "School name", "degree": "Degree name", "highlights": ["relevant focus area 1", "focus area 2"] } ],\n' +
  '  "tailoring_notes": "1-2 sentence note on what you emphasised for this job"\n' +
  '}';

const jobBlock = 'Target Job\n' +
  '- Title: ' + data.job_title + '\n' +
  '- Company: ' + data.company_name + '\n' +
  '- Location: ' + data.job_location + '\n' +
  '- Description: ' + (data.job_description || '').slice(0, 1500) + '\n' +
  '- Requirements: ' + (data.job_requirements || '').slice(0, 1000);

let prompt;
if (hasOriginal) {
  prompt = 'You are an expert resume writer. Below is the candidate real resume text, extracted from their PDF. ' +
    'Extract their REAL projects, work experience, education, and skills from it - do not invent companies, dates, ' +
    'schools, or projects that are not present in the source text. Then tailor the summary, bullet wording, and ' +
    'which skills or projects you foreground to best fit the target job below. Keep every fact (company names, ' +
    'dates, degree names) exactly as it appears in the source text.\n\n' +
    'Return ONLY valid JSON matching this exact shape, no markdown, no backticks:\n' + schema + '\n\n' +
    jobBlock + '\n\n' +
    'Candidate Resume Text (source of truth for all facts)\n' + originalResume;
} else {
  prompt = 'You are an expert resume writer. The candidate has not uploaded a resume yet, so build reasonable ' +
    'resume content from their profile below, tailored to the target job. Keep it realistic and modest - do not ' +
    'invent specific companies, project names, or schools. If you do not have real facts for experience, projects, ' +
    'or education, return an empty array for that field rather than inventing one, and rely on the summary and ' +
    'skills sections instead.\n\n' +
    'Return ONLY valid JSON matching this exact shape, no markdown, no backticks:\n' + schema + '\n\n' +
    'Candidate Profile\n' +
    '- Job Titles: ' + (jobTitles.join(', ') || 'Not specified') + '\n' +
    '- Experience: ' + (data.experience_years || 0) + ' years\n' +
    '- Skills: ' + (skills.join(', ') || 'Not specified') + '\n' +
    '- Industries: ' + (industries.length ? industries.join(', ') : 'General') + '\n\n' +
    jobBlock;
}

return [{
  json: {
    ...data,
    requestBody: {
      model: 'llama-3.1-8b-instant',
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.3,
      max_tokens: 2200,
    }
  }
}];

const groqResponse = $input.first().json;
const prevData = $('Build Tailor Prompt').first().json;

if (groqResponse.error) {
  throw new Error('Groq API error: ' + (groqResponse.error.message || JSON.stringify(groqResponse.error)));
}

let rawText = '';
try { rawText = groqResponse.choices[0].message.content; }
catch (e) { throw new Error('Failed to extract Groq response: ' + e.message); }

const cleanText = rawText.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;
try { parsed = JSON.parse(cleanText); }
catch (e) { throw new Error('Failed to parse JSON: ' + e.message + ' | Raw: ' + cleanText.substring(0, 300)); }

const asArray = function(v) { return Array.isArray(v) ? v : []; };

return [{
  json: {
    ...prevData,
    professional_summary: parsed.professional_summary || '',
    portfolio_url: parsed.portfolio_url || null,
    github_url: parsed.github_url || null,
    linkedin_url: parsed.linkedin_url || null,
    skill_groups: asArray(parsed.skill_groups),
    projects: asArray(parsed.projects),
    experience: asArray(parsed.experience),
    education: asArray(parsed.education),
    tailoring_notes: parsed.tailoring_notes || '',
  }
}];

const data = $input.first().json;

const e = function(str) { return (str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };

const skillGroups = Array.isArray(data.skill_groups) ? data.skill_groups : [];
const projects = Array.isArray(data.projects) ? data.projects : [];
const experience = Array.isArray(data.experience) ? data.experience : [];
const education = Array.isArray(data.education) ? data.education : [];

const linksLine = [
  data.portfolio_url ? 'Portfolio: ' + e(data.portfolio_url) : '',
  data.github_url ? 'GitHub: ' + e(data.github_url) : '',
  data.linkedin_url ? 'LinkedIn: ' + e(data.linkedin_url) : '',
].filter(Boolean).join(' | ');

const contactLine = [
  data.email ? 'Email: ' + e(data.email) : '',
  data.user_location ? e(data.user_location) : '',
  data.phone ? 'Phone: ' + e(data.phone) : '',
].filter(Boolean).join(' | ');

const skillsHtml = skillGroups.map(function(g) {
  const items = Array.isArray(g.items) ? g.items.join(', ') : '';
  return '<p class="skill-group"><strong>' + e(g.category) + ':</strong> ' + e(items) + '</p>';
}).join('
    ');

const projectsHtml = projects.map(function(p) {
  const bullets = (Array.isArray(p.bullets) ? p.bullets : []).map(function(b) { return '<li>' + e(b) + '</li>'; }).join('
        ');
  const titleLine = e(p.name) + (p.subtitle ? ' - ' + e(p.subtitle) : '') + (p.url ? ' (' + e(p.url) + ')' : '');
  return '<div class="entry">
      <div class="entry-title">' + titleLine + '</div>
      <ul class="bullets">
        ' + bullets + '
      </ul>
    </div>';
}).join('
    ');

const experienceHtml = experience.map(function(x) {
  const bullets = (Array.isArray(x.bullets) ? x.bullets : []).map(function(b) { return '<li>' + e(b) + '</li>'; }).join('
        ');
  return '<div class="entry">
      <div class="entry-row"><span class="entry-company">' + e(x.company) + '</span><span class="entry-dates">' + e(x.dates) + '</span></div>
      <div class="entry-role">' + e(x.role) + '</div>
      <ul class="bullets">
        ' + bullets + '
      </ul>
    </div>';
}).join('
    ');

const educationHtml = education.map(function(x) {
  const highlights = (Array.isArray(x.highlights) ? x.highlights : []).map(function(h) { return '<li>' + e(h) + '</li>'; }).join('
        ');
  return '<div class="entry">
      <div class="entry-title">' + e(x.institution) + '</div>
      <div class="entry-role">' + e(x.degree) + '</div>
      ' + (highlights ? '<ul class="bullets">
        ' + highlights + '
      </ul>' : '') + '
    </div>';
}).join('
    ');

const html = '<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Resume - ' + e(data.full_name) + '</title>
<style>
' +
'  * { margin: 0; padding: 0; box-sizing: border-box; }
' +
'  body {
' +
'    font-family: Georgia, "Times New Roman", serif;
' +
'    font-size: 10.5pt;
' +
'    color: #111111;
' +
'    background: #ffffff;
' +
'    line-height: 1.45;
' +
'    max-width: 740px;
' +
'    margin: 0 auto;
' +
'    padding: 48px 54px;
' +
'  }
' +
'  .header { text-align: center; padding-bottom: 12px; border-bottom: 1.5px solid #111111; margin-bottom: 20px; }
' +
'  .header h1 { font-size: 22pt; font-weight: 700; letter-spacing: 0.01em; margin-bottom: 6px; }
' +
'  .header .contact { font-size: 9.5pt; color: #222222; margin-bottom: 3px; }
' +
'  .header .links { font-size: 9.5pt; color: #222222; }
' +
'  section { margin-bottom: 18px; }
' +
