const seen = new Set();
const apiCalls = [];
const pushUnique = (call) => {
  const key = `${call.source}|${call.query}`;
  if (seen.has(key)) return;
  seen.add(key);
  apiCalls.push(call);
};

for (const profile of profiles) {
  const jobTitles = safeJSONParse(profile.job_titles);
