    loc.toLowerCase().includes('philippines') ||
    loc.toLowerCase().includes('manila') ||
    loc.toLowerCase().includes('taguig') ||
    loc.toLowerCase().includes('bgc') ||
    loc.toLowerCase().includes('makati') ||
    loc.toLowerCase().includes('quezon')
