  topJobTitles.forEach(jobTitle => {
    if (hasPhilippines) pushUnique({ source: 'jsearch', url: 'https://jsearch.p.rapidapi.com/search', query: `${jobTitle} Philippines`, jobTitle, location: 'Philippines', requiresRapidAPI: true, isRSS: false });
    pushUnique({ source: 'jsearch', url: 'https://jsearch.p.rapidapi.com/search', query: `${jobTitle} Remote`, jobTitle, location: 'Remote', requiresRapidAPI: true, isRSS: false });
