pushUnique({ source: 'weworkremotely_rss', url: 'https://weworkremotely.com/categories/remote-programming-jobs.rss', query: 'Remote Programming', jobTitle: 'Programmer', location: 'Remote', requiresRapidAPI: false, isRSS: true });

