.tp-topic { font-weight: 600; color: #1e3a5f; width: 22%; }
.tp-point { width: 62%; color: #374151; }
.tp-source { width: 16%; font-size: 8pt; font-weight: 700; text-transform: uppercase; text-align: center; padding: 4px 8px; border-radius: 10px; }
.badge-website { background: #dbeafe; color: #1d4ed8; }
.badge-news { background: #dcfce7; color: #15803d; }
.badge-job_description { background: #fef9c3; color: #854d0e; }
ul.items { padding-left: 18px; }
ul.items li { margin-bottom: 6px; line-height: 1.55; color: #374151; }
.flag li { color: #b91c1c; }
.footer-note { margin-top: 24px; border-top: 1px solid #e5e7eb; padding-top: 10px; font-size: 8pt; color: #9ca3af; text-align: center; }
</style>
</head>
<body>
<div class="header">
  <h1>&#128269; Company Research Brief</h1>
  <div class="sub">Prepared for: <strong>${e(d.full_name)}</strong> &nbsp;&bull;&nbsp; Role: <strong>${e(d.job_title)}</strong> at <strong>${e(d.company_name)}</strong></div>
</div>
<div class="meta-bar">
  <span><strong>Company:</strong> ${e(d.company_name)}</span>
  <span><strong>Location:</strong> ${e(d.job_location)}</span>
  <span><strong>Date:</strong> ${today}</span>
  <span class="confidence">Data Confidence: ${scoreLabel} (${score}/100)</span>
</div>

<section>
  <div class="stitle">Company Overview</div>
  <div class="card">${e(d.company_overview || 'Not available.')}</div>
</section>

<section>
  <div class="stitle">Mission &amp; Values</div>
  <div class="card">${e(d.mission_and_values || 'Not available.')}</div>
</section>

<section>
  <div class="stitle">Recent Developments</div>
  <ul class="items">${devsHtml || '<li>No recent developments found.</li>'}</ul>
</section>

<section>
  <div class="stitle">Why They Are Hiring</div>
  <div class="card">${e(d.why_they_are_hiring || 'Not determined.')}</div>
</section>

<section>
  <div class="stitle">Interview Talking Points</div>
  <table class="tp">
    <thead>
      <tr><th>Topic</th><th>What to Say</th><th>Source</th></tr>
    </thead>
    <tbody>${tpRows || '<tr><td colspan="3">No talking points generated.</td></tr>'}</tbody>
  </table>
</section>

<section>
  <div class="stitle">Smart Questions to Ask the Interviewer</div>
  <ul class="items">${questionsHtml || '<li>No questions generated.</li>'}</ul>
</section>

<section>
  <div class="stitle">&#9888; Points to Clarify / Red Flags</div>
  <ul class="items flag">${flagsHtml || '<li>None identified.</li>'}</ul>
</section>

<section>
  <div class="stitle">Research Notes</div>
  <div class="card" style="font-style: italic; color: #6b7280;">${e(d.research_notes || '')}</div>
</section>

<div class="footer-note">Generated by Match AI &bull; ${today} &bull; Always verify with your own research before interviews.</div>
</body>
</html>`;

return [{
  json: {
    ...d,
    research_html: html
  }
}];

const aiData = $('Parse Research Response').first().json;
const now = new Date().toISOString();

// In filesystem binaryDataMode, check for binary key existence only
const hasBinary = !!$input.first().binary?.data;

return [{
  json: {
    ...aiData,
    pdf_binary: null,
    pdf_generated: hasBinary,
    created_at: now,
    talking_points_json: JSON.stringify(aiData.talking_points || []),
    recent_developments_json: JSON.stringify(aiData.recent_developments || []),
    questions_json: JSON.stringify(aiData.questions_to_ask || []),
    red_flags_json: JSON.stringify(aiData.red_flags || [])
  }
}];

const body = $input.first().json.body || $input.first().json;

const action = (body.action || '').trim();
const user_id = body.user_id;
const job_id = body.job_id || null;
const application_id = body.application_id || null;
const status = (body.status || '').trim() || null;
const interview_date = body.interview_date || null;
const interview_location = body.interview_location || null;
const interview_type = (body.interview_type || 'video').trim();
const interviewer_name = body.interviewer_name || null;
const interviewer_role = body.interviewer_role || null;
const notes = body.notes || null;

const validActions = ['create', 'update_status', 'schedule_interview'];
const validStatuses = ['interested', 'applied', 'phone_screen', 'interview', 'final_round', 'offer', 'rejected', 'withdrawn', 'accepted'];

if (!action || !validActions.includes(action)) {
  throw new Error(`Invalid or missing action. Must be one of: ${validActions.join(', ')}`);
}
if (!user_id) {
  throw new Error('Missing required field: user_id');
}
if (action === 'create' && !job_id) {
  throw new Error('action=create requires job_id');
}
if (action === 'update_status' && !application_id) {
  throw new Error('action=update_status requires application_id');
}
if (action === 'update_status') {
  if (!status || !validStatuses.includes(status)) {
    throw new Error(`Invalid status "${status}". Must be one of: ${validStatuses.join(', ')}`);
  }
}
if (action === 'schedule_interview' && !application_id) {
  throw new Error('action=schedule_interview requires application_id');
}
if (action === 'schedule_interview' && !interview_date) {
  throw new Error('action=schedule_interview requires interview_date (ISO 8601)');
}

return [{
  json: {
    action,
    user_id: String(user_id),
    job_id: job_id ? parseInt(job_id) : null,
    application_id: application_id ? parseInt(application_id) : null,
    status,
    interview_date,
    interview_location,
    interview_type,
    interviewer_name,
    interviewer_role,
    notes
  }
}];

const result = $input.first().json;

if (!result || !result.application_id) {
  throw new Error('Application action failed — no record returned. Check user_id, application_id, and job_id exist in the database.');
}

return [{ json: result }];

const body = $input.first().json.body || $input.first().json;

const followup_id = body.followup_id;
const application_id = body.application_id;
const user_id = body.user_id;
const response_status = (body.response_status || '').trim();

const validStatuses = ['replied', 'no_response', 'bounced'];

if (!followup_id) throw new Error('Missing followup_id');
if (!application_id) throw new Error('Missing application_id');
if (!user_id) throw new Error('Missing user_id');
if (!validStatuses.includes(response_status)) {
  throw new Error('Invalid response_status. Must be one of: ' + validStatuses.join(', '));
}

return [{
  json: {
    followup_id: parseInt(followup_id),
    application_id: parseInt(application_id),
    user_id: String(user_id),
    response_status
  }
}];

const body = $input.first().json.body || $input.first().json;

const user_id = body.user_id;
const application_id = body.application_id;
const interviewer_name = (body.interviewer_name || '').trim() || null;
const interviewer_role = (body.interviewer_role || '').trim() || null;
const interviewer_linkedin_url = (body.interviewer_linkedin_url || '').trim() || null;

if (!user_id) throw new Error('Missing required field: user_id');
if (!application_id) throw new Error('Missing required field: application_id');

return [{
  json: {
    user_id: String(user_id),
    application_id: parseInt(application_id),
    interviewer_name,
    interviewer_role,
    interviewer_linkedin_url
  }
}];

const prepData = $('Prepare Prep Data').first().json;

return [{
  json: {
    ...prepData,
    interviewer_bio: null,
    linkedin_scraped: false
  }
}];

const d = $input.first().json;

const skills = Array.isArray(d.skills) ? d.skills.join(', ') : 'Not specified';
const jobTitles = Array.isArray(d.job_titles) ? d.job_titles.join(', ') : 'Not specified';

const interviewerSection = d.interviewer_name
  ? `\n## Interviewer\n- Name: ${d.interviewer_name}\n- Role: ${d.interviewer_role || 'Not specified'}\n`
  : '';

const companyResearchSection = d.has_company_research
  ? `\n## Company Research on File\n- Overview: ${d.company_overview || 'Not available'}\n- Mission & Values: ${d.mission_and_values || 'Not available'}\n- Talking Points: ${d.company_talking_points || 'Not available'}\n`
  : '';

const prompt = `You are a senior career coach and interview preparation specialist. A candidate has an upcoming interview for the role below. Using the information provided, produce a comprehensive, personalised interview preparation guide.

## Candidate Background
- Name: ${d.full_name}
- Target Role: ${d.job_title}
- Skills: ${skills}
- Previous Job Titles: ${jobTitles}
- Experience: ${d.experience_years || 0} years

## Company & Interview Logistics
- Company Name: ${d.company_name}
- Location: ${d.job_location}
- Website: ${d.company_url || 'Not available'}
- Interview Type: ${d.interview_type || 'video'}
- Interview Date: ${d.interview_date || 'Not scheduled'}
${interviewerSection}${companyResearchSection}
## Job Description
${d.job_description}

## Job Requirements
${d.job_requirements || 'Not specified'}

---

Return ONLY a valid JSON object with no markdown, no backticks, no extra text:
{
  "role_analysis": "<3–4 sentence analysis of what this role really needs, based on the job description and requirements>",
  "questions": {
    "behavioural": [
      { "question": "<Likely behavioural question 1>", "why_asked": "<What the interviewer is testing>", "tip": "<How to answer well>" },
      { "question": "<Likely behavioural question 2>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely behavioural question 3>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely behavioural question 4>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely behavioural question 5>", "why_asked": "<...>", "tip": "<...>" }
    ],
    "technical": [
      { "question": "<Likely technical question 1>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely technical question 2>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely technical question 3>", "why_asked": "<...>", "tip": "<...>" }
    ],
    "culture_fit": [
      { "question": "<Likely culture-fit question 1>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely culture-fit question 2>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely culture-fit question 3>", "why_asked": "<...>", "tip": "<...>" }
    ],
    "situational": [
      { "question": "<Likely situational question 1>", "why_asked": "<...>", "tip": "<...>" },
      { "question": "<Likely situational question 2>", "why_asked": "<...>", "tip": "<...>" }
    ]
  },
  "star_answers": [
    { "question": "<One of the behavioural/situational questions above>", "situation": "<Suggested situation drawn from the candidate's background>", "task": "<Task>", "action": "<Action>", "result": "<Result>" },
    { "question": "<Another question above>", "situation": "<...>", "task": "<...>", "action": "<...>", "result": "<...>" },
    { "question": "<Another question above>", "situation": "<...>", "task": "<...>", "action": "<...>", "result": "<...>" }
  ],
  "interviewer_insights": "<Notes on the interviewer's likely focus/style based on their name/role if provided, else general guidance on who typically runs this kind of interview — 1-2 sentences>",
  "questions_to_ask": [
    "<Smart question the candidate can ask the interviewer>",
    "<Smart question 2>",
    "<Smart question 3>"
  ],
  "dos_and_donts": {
    "dos": ["<Do 1>", "<Do 2>", "<Do 3>"],
    "donts": ["<Don't 1>", "<Don't 2>", "<Don't 3>"]
  },
  "salary_guidance": "<Brief, practical guidance on handling salary discussion for this specific role/level>",
  "prep_notes": "<Brief note on data quality and anything the candidate should independently verify before the interview>"
}`;

// Gemini's generateContent API expects `{ contents: [{ parts: [{ text }] }] }`
// with sampling parameters under a separate `generationConfig` key — not the
// OpenAI-style `{ model, messages, response_format }` shape used by Groq.
// `model` is already part of the request URL on the "Gemini · Generate Prep"
// node (generativelanguage.googleapis.com/.../models/gemini-2.0-flash:generateContent),
// not the body, and auth is handled by that node's googlePalmApi credential.
return [{
  json: {
    ...d,
    requestBody: {
      contents: [
        { parts: [{ text: prompt }] }
      ],
      generationConfig: {
        temperature: 0.3,
        maxOutputTokens: 3000,
        responseMimeType: 'application/json'
      }
    }
  }
}];

const context = $('Build Prep Prompt').first().json;
const raw = $input.first().json;

let aiText = '';
try {
  aiText = raw.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch(e) { aiText = ''; }

const clean = aiText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    role_analysis: 'Could not generate role analysis. Please review the job description manually.',
    questions: {
      behavioural: [
        { question: 'Tell me about yourself.', why_asked: 'Standard opener to assess communication and background fit.', tip: 'Keep it to 2 minutes and tie it to the role.' },
        { question: 'Describe a challenging project you led.', why_asked: 'Assesses leadership and problem-solving.', tip: 'Use the STAR format.' }
      ],
      technical: [
        { question: 'Walk me through your technical approach to a recent project.', why_asked: 'Tests depth of technical knowledge.', tip: 'Be specific, not generic.' }
      ],
      culture_fit: [
        { question: 'How do you prefer to work — independently or in a team?', why_asked: 'Culture alignment check.', tip: 'Show flexibility.' }
      ],
      situational: [
        { question: 'What would you do in your first 30 days?', why_asked: 'Tests initiative and preparation.', tip: 'Show you have done your research.' }
      ]
    },
    star_answers: [],
    interviewer_insights: 'No interviewer data provided.',
    questions_to_ask: [
      'What does success look like in the first 90 days?',
      'What are the biggest challenges facing the team right now?',
      'How would you describe the team culture?'
    ],
    dos_and_donts: {
      dos: ['Research the company beforehand', 'Bring specific examples', 'Ask thoughtful questions'],
      donts: ['Speak negatively about past employers', 'Give vague answers', 'Forget to follow up']
    },
    salary_guidance: 'Let the interviewer bring up salary first. If pressed, give a range based on your research.',
    prep_notes: 'AI parsing failed — fallback questions provided. Review job description carefully before the interview.'
  };
}

return [{
  json: {
    ...context,
    ...parsed,
    questions_json: JSON.stringify(parsed.questions || {}),
    star_answers_json: JSON.stringify(parsed.star_answers || []),
    questions_to_ask_json: JSON.stringify(parsed.questions_to_ask || []),
    dos_and_donts_json: JSON.stringify(parsed.dos_and_donts || {})
  }
}];

const d = $('Parse Prep Response').first().json;
const pdfBinary = $input.first().binary?.data
  ? Buffer.from($input.first().binary.data, 'base64').toString('base64')
  : null;

return [{
  json: {
    ...d,
    pdf_binary: pdfBinary,
    pdf_generated: !!pdfBinary,
    created_at: new Date().toISOString()
  }
}];
